import torch
import torch.nn as nn
import torch.nn.functional as F
import triton
import triton.language as tl


@triton.jit
def _add_expanded_bias_kernel(
    x_ptr,
    bias_ptr,
    out_ptr,
    n_elements,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < n_elements

    x = tl.load(x_ptr + offs, mask=mask)
    bias = tl.load(bias_ptr + offs, mask=mask)
    out = x + bias

    tl.store(out_ptr + offs, out, mask=mask)


def _add_expanded_bias(x, bias):
    x = x.contiguous()
    bias = bias.expand_as(x).contiguous()

    out = torch.empty_like(x)
    n_elements = x.numel()
    BLOCK = 1024
    grid = (triton.cdiv(n_elements, BLOCK),)

    _add_expanded_bias_kernel[grid](
        x,
        bias,
        out,
        n_elements,
        BLOCK=BLOCK,
    )
    return out


class ModelNew(nn.Module):
    def __init__(self, norm_type, num_channels):
        super().__init__()
        if norm_type == "batch":
            self.norm = nn.BatchNorm2d(num_channels)
        elif norm_type == "instance":
            self.norm = nn.InstanceNorm2d(num_channels)
        elif norm_type == "layer":
            self.norm = nn.LayerNorm(num_channels)
        else:
            raise ValueError(
                "Invalid normalization type. Choose 'batch', 'instance', or 'layer'."
            )

    def forward(self, x):
        if isinstance(self.norm, nn.BatchNorm2d):
            if self.norm.momentum is None:
                exponential_average_factor = 0.0
            else:
                exponential_average_factor = self.norm.momentum

            if self.training and self.norm.track_running_stats:
                if self.norm.num_batches_tracked is not None:
                    self.norm.num_batches_tracked.add_(1)
                    if self.norm.momentum is None:
                        exponential_average_factor = (
                            1.0 / float(self.norm.num_batches_tracked)
                        )
                    else:
                        exponential_average_factor = self.norm.momentum

            if self.training:
                bn_training = True
            else:
                bn_training = (
                    self.norm.running_mean is None
                    and self.norm.running_var is None
                )

            running_mean = (
                self.norm.running_mean
                if not self.training or self.norm.track_running_stats
                else None
            )
            running_var = (
                self.norm.running_var
                if not self.training or self.norm.track_running_stats
                else None
            )

            x = F.batch_norm(
                x,
                running_mean,
                running_var,
                self.norm.weight,
                None,
                bn_training,
                exponential_average_factor,
                self.norm.eps,
            )

            if self.norm.bias is not None:
                channel_bias = self.norm.bias.reshape(1, -1, 1, 1)
                x = _add_expanded_bias(x, channel_bias)

            return x

        if isinstance(self.norm, nn.LayerNorm):
            x = F.layer_norm(
                x,
                self.norm.normalized_shape,
                self.norm.weight,
                None,
                self.norm.eps,
            )
            if self.norm.bias is not None:
                x = _add_expanded_bias(x, self.norm.bias)
            return x

        return self.norm(x)

import torch
import torch.nn as nn
import triton
import triton.language as tl


@triton.jit
def _variance_eps_kernel(var_ptr, out_ptr, n_elements, eps, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < n_elements
    var = tl.load(var_ptr + offs, mask=mask)
    adjusted_var = var + eps
    tl.store(out_ptr + offs, adjusted_var, mask=mask)


def _variance_eps(var, eps):
    var = var.contiguous()
    out = torch.empty_like(var)
    n_elements = var.numel()
    BLOCK = 256
    grid = (triton.cdiv(n_elements, BLOCK),)
    _variance_eps_kernel[grid](
        var,
        out,
        n_elements,
        eps,
        BLOCK=BLOCK,
    )
    return out


class ModelNew(nn.Module):
    def __init__(
        self,
        num_features,
        eps=1e-5,
        momentum=0.1,
        affine=True,
        track_running_stats=True,
    ):
        super().__init__()
        self.batch_norm = nn.BatchNorm3d(
            num_features,
            eps=eps,
            momentum=momentum,
            affine=affine,
            track_running_stats=track_running_stats,
        )

    def forward(self, x):
        bn = self.batch_norm
        reduction_dims = (0, 2, 3, 4)

        use_batch_stats = self.training or (
            bn.running_mean is None or bn.running_var is None
        )

        if use_batch_stats:
            mean = torch.mean(x, dim=reduction_dims)
            var = torch.var(x, dim=reduction_dims, unbiased=False)

            if self.training and bn.track_running_stats:
                if bn.num_batches_tracked is not None:
                    with torch.no_grad():
                        bn.num_batches_tracked.add_(1)

                    if bn.momentum is None:
                        exponential_average_factor = (
                            1.0 / float(bn.num_batches_tracked.item())
                        )
                    else:
                        exponential_average_factor = bn.momentum
                else:
                    exponential_average_factor = (
                        0.0 if bn.momentum is None else bn.momentum
                    )

                elements_per_channel = x.numel() // x.shape[1]

                with torch.no_grad():
                    detached_mean = mean.detach()
                    detached_var = var.detach()

                    if elements_per_channel > 1:
                        detached_var = detached_var * (
                            float(elements_per_channel)
                            / float(elements_per_channel - 1)
                        )

                    bn.running_mean.mul_(
                        1.0 - exponential_average_factor
                    ).add_(
                        detached_mean,
                        alpha=exponential_average_factor,
                    )
                    bn.running_var.mul_(
                        1.0 - exponential_average_factor
                    ).add_(
                        detached_var,
                        alpha=exponential_average_factor,
                    )
        else:
            mean = bn.running_mean
            var = bn.running_var

        adjusted_var = _variance_eps(var, bn.eps)
        invstd = torch.rsqrt(adjusted_var)

        broadcast_shape = (1, x.shape[1], 1, 1, 1)
        out = x.clone()
        out.sub_(mean.reshape(broadcast_shape))
        out.mul_(invstd.reshape(broadcast_shape))

        if bn.affine:
            out.mul_(bn.weight.reshape(broadcast_shape))
            out.add_(bn.bias.reshape(broadcast_shape))

        return out
